#include <iostream>

int main() {
    int a = 0;
    int b = 0;

    if (std::cin >> a >> b) {
        std::cout << "Input values: a = " << a << ", b = " << b << "\n";
        if (b == 0) {
            // Defensive programming against fatal runtime error (division by zero)
            std::cerr << "Error: Division by zero is undefined!\n";
            return 1;
        } else {
            std::cout << "Result: " << (a / b) << "\n";
        }
    } else {
        std::cerr << "Error: Failed to read integers.\n";
        return 1;
    }

    return 0;
}

#include <iostream>

int main() {
    // Fixed target for deterministic test-drive demonstration
    constexpr int target = 500;
    int guess = 0;

    std::cout << "Guess a number between 1 and 1000.\n";
    while (std::cin >> guess) {
        std::cout << "Entered: " << guess << "\n";
        if (guess < target) {
            std::cout << "Too low. Try again.\n";
        } else if (guess > target) {
            std::cout << "Too high. Try again.\n";
        } else {
            std::cout << "Excellent! You guessed the number!\n";
            break;
        }
    }

    return 0;
}
